export const LanguageProvider = ({ children }) => {
  const [currentLanguage, setCurrentLanguage] = useState(() => {
    return localStorage.getItem('scheme_sathi_lang') || 'en';
  });

  const setLanguage = (langCode) => {
    setCurrentLanguage(langCode);
    localStorage.setItem('scheme_sathi_lang', langCode);
    document.documentElement.lang = langCode;
  };

  useEffect(() => {
    document.documentElement.lang = currentLanguage;
  }, [currentLanguage]);

  const normalizeKey = (str) => {
    if (!str || typeof str !== 'string') return '';
    return str.trim().toLowerCase().replace(/[:.,?!]+$/, '');
  };

  const t = (key, fallback = '') => {
    if (!key && !fallback) return '';
    const primaryKey = String(key || '').trim();
    const fallbackKey = String(fallback || '').trim();
    const searchKey = primaryKey || fallbackKey;
    if (!searchKey) return '';
    if (currentLanguage === 'en') return fallbackKey || searchKey;

    const langDict = DICTIONARY[currentLanguage];

    // 1. Direct exact match in Dictionary for primaryKey
    if (primaryKey && langDict && langDict[primaryKey] && langDict[primaryKey] !== primaryKey) {
      return langDict[primaryKey];
    }

    // 2. Direct exact match in Dictionary for fallbackKey
    if (fallbackKey && langDict && langDict[fallbackKey] && langDict[fallbackKey] !== fallbackKey) {
      return langDict[fallbackKey];
    }

    // 3. Exact match in PHRASE_MAP for primaryKey
    if (primaryKey && PHRASE_MAP[primaryKey] && PHRASE_MAP[primaryKey][currentLanguage] && PHRASE_MAP[primaryKey][currentLanguage] !== primaryKey) {
      return PHRASE_MAP[primaryKey][currentLanguage];
    }

    // 4. Exact match in PHRASE_MAP for fallbackKey
    if (fallbackKey && PHRASE_MAP[fallbackKey] && PHRASE_MAP[fallbackKey][currentLanguage] && PHRASE_MAP[fallbackKey][currentLanguage] !== fallbackKey) {
      return PHRASE_MAP[fallbackKey][currentLanguage];
    }

    // 5. Normalized search (case-insensitive & stripped punctuation)
    const normPrimary = normalizeKey(primaryKey);
    const normFallback = normalizeKey(fallbackKey);
    const normTarget = normPrimary || normFallback;

    if (langDict && normTarget) {
      for (const [k, v] of Object.entries(langDict)) {
        if (normalizeKey(k) === normTarget && v && v !== k) {
          return (primaryKey.endsWith(':') || fallbackKey.endsWith(':')) && !v.endsWith(':') ? `${v}:` : v;
        }
      }
    }

    if (normTarget) {
      for (const [k, transMap] of Object.entries(PHRASE_MAP)) {
        if (normalizeKey(k) === normTarget && transMap[currentLanguage] && transMap[currentLanguage] !== k) {
          const v = transMap[currentLanguage];
          return (primaryKey.endsWith(':') || fallbackKey.endsWith(':')) && !v.endsWith(':') ? `${v}:` : v;
        }
      }
    }

    // 6. Dynamic Regex Patterns
    const stageMatch = searchKey.match(/^Stage (\d+) of (\d+)$/i);
    if (stageMatch) {
      const [_, st, tot] = stageMatch;
      const stageWord = t('Stage') || 'चरण';
      return `${stageWord} ${st} / ${tot}`;
    }

    const yearMatch = searchKey.match(/^Year (\d+)$/i);
    if (yearMatch) {
      const yrWord = t('Year') || 'वर्ष';
      return `${yrWord} ${yearMatch[1]}`;
    }

    const manMatch = searchKey.match(/^(\d+) of (\d+) Mandatory Verified$/i);
    if (manMatch) {
      return `${manMatch[1]} / ${manMatch[2]} ${t('Mandatory Verified') || 'अनिवार्य सत्यापित'}`;
    }

    const matchCount = searchKey.match(/^(\d+) Matches Found$/i);
    if (matchCount) {
      return `${matchCount[1]} ${t('Matches Found') || 'योजनाएं मिलीं'}`;
    }

    // 7. If dictionary has an entry (even if identical in fallback), return it
    if (langDict && langDict[searchKey]) {
      return langDict[searchKey];
    }

    return fallbackKey || searchKey;
  };

  const translateScheme = (scheme) => {
    if (!scheme) return scheme;
    if (currentLanguage === 'en') return scheme;

    const code = (scheme.code || scheme.scheme_code || '').toUpperCase();
    const localized = SCHEME_MAP[code] ? SCHEME_MAP[code][currentLanguage] : null;

    const translatedDept = t(scheme.department);
    const translatedMinistry = t(scheme.ministry);
    const translatedCat = t(scheme.category || scheme.target_category);

    if (localized) {
      return {
        ...scheme,
        name: localized.name || scheme.name,
        scheme_name: localized.name || scheme.scheme_name,
        description: localized.desc || scheme.description,
        scheme_description: localized.desc || scheme.scheme_description,
        department: translatedDept || scheme.department,
        ministry: translatedMinistry || scheme.ministry,
        category: translatedCat || scheme.category,
        target_category: translatedCat || scheme.target_category
      };
    }

    return {
      ...scheme,
      name: t(scheme.name || scheme.scheme_name),
      scheme_name: t(scheme.scheme_name || scheme.name),
      description: t(scheme.description || scheme.scheme_description),
      scheme_description: t(scheme.scheme_description || scheme.description),
      department: translatedDept || scheme.department,
      ministry: translatedMinistry || scheme.ministry,
      category: translatedCat || scheme.category,
      target_category: translatedCat || scheme.target_category
    };
  };

  const translateDynamic = async (text) => {
    if (!text || currentLanguage === 'en') return text;
    try {
      const res = await api.post('/translate', {
        text: text,
        target_language: currentLanguage
      });
      return res.data.translated_text || text;
    } catch (e) {
      return text;
    }
  };

  return (
    <LanguageContext.Provider value={{
      currentLanguage,
      language: currentLanguage,
      setLanguage,
      t,
      translateScheme,
      translateDynamic,
      languages: LANGUAGES
    }}>
      {children}
    </LanguageContext.Provider>
  );
};

export const useLanguage = () => useContext(LanguageContext);
